import pytest
from candidate import modp


class TestModpBasic:
    def test_modp_basic_example_3_5(self):
        assert modp(3, 5) == 3

    def test_modp_basic_example_3_11(self):
        assert modp(3, 11) == 8

    def test_modp_zero_exponent(self):
        assert modp(0, 101) == 1

    def test_modp_zero_exponent_p5(self):
        assert modp(0, 5) == 1

    def test_modp_zero_exponent_p2(self):
        assert modp(0, 2) == 1

    def test_modp_zero_exponent_p1000(self):
        assert modp(0, 1000) == 1

    def test_modp_one_exponent(self):
        assert modp(1, 5) == 2

    def test_modp_one_exponent_p2(self):
        assert modp(1, 2) == 0

    def test_modp_one_exponent_p3(self):
        assert modp(1, 3) == 2

    def test_modp_large_exponent_1101_101(self):
        assert modp(1101, 101) == 2

    def test_modp_fermat_100_101(self):
        assert modp(100, 101) == 1


class TestModpModuloPatterns:
    def test_modp_p2_positive_n(self):
        for n in range(1, 15):
            assert modp(n, 2) == 0

    def test_modp_p3_cycle(self):
        expected = [2, 1, 2, 1, 2, 1, 2, 1, 2, 1]
        for n, exp in enumerate(expected, start=1):
            assert modp(n, 3) == exp

    def test_modp_p7_cycle(self):
        assert modp(1, 7) == 2
        assert modp(2, 7) == 4
        assert modp(3, 7) == 1
        assert modp(4, 7) == 2
        assert modp(5, 7) == 4
        assert modp(6, 7) == 1
        assert modp(7, 7) == 2

    def test_modp_p5_cycle(self):
        assert modp(1, 5) == 2
        assert modp(2, 5) == 4
        assert modp(3, 5) == 3
        assert modp(4, 5) == 1
        assert modp(5, 5) == 2

    def test_modp_p11_values(self):
        assert modp(1, 11) == 2
        assert modp(2, 11) == 4
        assert modp(3, 11) == 8
        assert modp(4, 11) == 5
        assert modp(5, 11) == 10
        assert modp(10, 11) == 1


class TestModpEdgeCases:
    def test_modp_negative_n_returns_one(self):
        assert modp(-1, 5) == 1

    def test_modp_negative_n_returns_one_p7(self):
        assert modp(-5, 7) == 1

    def test_modp_negative_large_n(self):
        assert modp(-100, 13) == 1

    def test_modp_p1_zero_n(self):
        assert modp(0, 1) == 1

    def test_modp_p1_positive_n(self):
        assert modp(1, 1) == 0

    def test_modp_p1_large_n(self):
        assert modp(100, 1) == 0

    def test_modp_n_equals_p(self):
        assert modp(5, 5) == pow(2, 5, 5)

    def test_modp_n_greater_than_p(self):
        assert modp(10, 3) == pow(2, 10, 3)

    def test_modp_n_equals_p_minus_one(self):
        assert modp(10, 11) == 1


class TestModpLargeValues:
    def test_modp_large_n_small_p(self):
        assert modp(1000, 7) == pow(2, 1000, 7)

    def test_modp_large_n_medium_p(self):
        assert modp(50000, 97) == pow(2, 50000, 97)

    def test_modp_large_p(self):
        p = 2**61 - 1
        assert modp(10, p) == pow(2, 10, p)

    def test_modp_large_p_large_n(self):
        p = 999999937
        assert modp(1000, p) == pow(2, 1000, p)

    def test_modp_computationally_expensive(self):
        assert modp(10000, 1009) == pow(2, 10000, 1009)


class TestModpCorrectness:
    def test_modp_matches_builtin_pow_various(self):
        for n in [0, 1, 2, 3, 4, 5, 10, 25, 50, 100, 255, 1000]:
            for p in [2, 3, 5, 7, 13, 17, 31, 101, 251]:
                assert modp(n, p) == pow(2, n, p)

    def test_modp_prime_modulus(self):
        primes = [3, 7, 13, 41, 101, 257, 1009]
        for p in primes:
            assert modp(p - 1, p) == 1

    def test_modp_composite_modulus(self):
        composites = [4, 6, 8, 12, 15, 21, 26]
        for p in composites:
            assert modp(10, p) == pow(2, 10, p)

    def test_modp_returns_int_type(self):
        result = modp(5, 7)
        assert isinstance(result, int)

    def test_modp_zero_returns_int_type(self):
        result = modp(0, 100)
        assert isinstance(result, int)


class TestModpTypeErrors:
    def test_modp_float_n_raises_type_error(self):
        with pytest.raises(TypeError):
            modp(3.5, 5)

    def test_modp_none_n_raises_type_error(self):
        with pytest.raises(TypeError):
            modp(None, 5)

    def test_modp_none_p_raises_type_error(self):
        with pytest.raises(TypeError):
            modp(3, None)

    def test_modp_string_n_raises_type_error(self):
        with pytest.raises(TypeError):
            modp("3", 5)

    def test_modp_string_p_raises_type_error(self):
        with pytest.raises(TypeError):
            modp(3, "5")

    def test_modp_list_n_raises_type_error(self):
        with pytest.raises(TypeError):
            modp([1, 2], 5)

    def test_modp_zero_p_none_n_raises(self):
        with pytest.raises(TypeError):
            modp(None, None)


class TestModpNumerics:
    def test_modp_no_overflow_large_intermediate(self):
        assert modp(200, 1000000007) == pow(2, 200, 1000000007)

    def test_modp_intermediate_stays_small(self):
        assert modp(10000, 1009) == pow(2, 10000, 1009)

    def test_modp_powers_of_two_modulus(self):
        assert modp(10, 8) == pow(2, 10, 8)

    def test_modp_n_exactly_p_minus_1(self):
        assert modp(14, 15) == 1

    def test_modp_consistency_across_runs(self):
        assert modp(50, 17) == modp(50, 17)
